### Camera Shake System (Trauma-Based)
```javascript
// In shared/vfx/cameraShake.js
class CameraShake {
  constructor(camera) {
    this.camera = camera;
    this.intensity = 0;
    this.decayRate = 0.92;
    this.originalPosition = camera.position.clone();
  }

  addTrauma(impactVelocity) {
    // Scale shake by impact severity
    const baseShake = 0.3;
    const velocityScale = Math.min(impactVelocity / 10, 2);
    this.intensity += (baseShake + velocityScale) * 0.5;
  }

  update() {
    if (this.intensity <= 0.001) return;

    const angle = Math.random() * Math.PI * 2;
    const offsetX = Math.cos(angle) * this.intensity;
    const offsetY = Math.sin(angle) * this.intensity;

    this.camera.position.x = this.originalPosition.x + offsetX;
    this.camera.position.y = this.originalPosition.y + offsetY;

    this.intensity *= this.decayRate;
  }
}

// Usage: cameraShake.addTrauma(projectile.velocity.length()) on collision
