### Motion Trails Implementation
```javascript
// In shared/vfx/motionTrails.js
class MotionTrailRenderer {
  constructor(maxSegments = 10) {
    this.maxSegments = maxSegments;
    this.trails = new Map(); // objectID → TrailData
  }

  add(object, color, thickness) {
    const id = object.id || Math.random();
    this.trails.set(id, {
      positions: [],           // History buffer (maxSegments Vector3s)
      color: new THREE.Color(color),
      thickness: thickness,
      geometry: null,          // Created on first update
      mesh: null
    });
  }

  update(object) {
    const trail = this.trails.get(object.id);
    if (!trail) return;

    // Push current position to history
    trail.positions.push(object.position.clone());

    // Maintain max length (FIFO)
    if (trail.positions.length > this.maxSegments) {
      trail.positions.shift();
    }

    // Update ribbon geometry
    if (trail.positions.length >= 2) {
      this.updateTrailGeometry(trail);
    }
  }

  updateTrailGeometry(trail) {
    // Create strip of quads along path
    const positions = [];
    const colors = [];

    for (let i = 0; i < trail.positions.length - 1; i++) {
      const t = i / trail.positions.length; // Alpha fade from tail to head
      const p1 = trail.positions[i];
      const p2 = trail.positions[i + 1];

      // Generate quad vertices perpendicular to motion direction
      const dir = new THREE.Vector3().subVectors(p2, p1).normalize();
      const right = new THREE.Vector3(-dir.z, 0, dir.x); // Perpendicular in XZ plane

      const halfWidth = trail.thickness * (t + 0.5) / 2;

      positions.push(
        p1.x - right.x * halfWidth, p1.y, p1.z - right.z * halfWidth,
        p1.x + right.x * halfWidth, p1.y, p1.z + right.z * halfWidth,
        p2.x + right.x * halfWidth, p2.y, p2.z + right.z * halfWidth,
        p2.x - right.x * halfWidth, p2.y, p2.z - right.z * halfWidth
      );

      // Color with alpha fade
      const alpha = t;
      colors.push(
        trail.color.r, trail.color.g, trail.color.b, alpha,
        trail.color.r, trail.color.g, trail.color.b, alpha,
        trail.color.r, trail.color.g, trail.color.b, alpha,
        trail.color.r, trail.color.g, trail.color.b, alpha
      );
    }

    // Update or create geometry
    if (!trail.geometry) {
      trail.geometry = new THREE.BufferGeometry();
      trail.geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      trail.geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 4));

      const material = new THREE.MeshBasicMaterial({ 
        vertexColors: true, 
        transparent: true,
        side: THREE.DoubleSide,
        blending: THREE.AdditiveBlending
      });

      trail.mesh = new THREE.Mesh(trail.geometry, material);
      scene.add(trail.mesh);
    } else {
      trail.geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
      trail.geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 4));
      trail.geometry.attributes.position.needsUpdate = true;
      trail.geometry.attributes.color.needsUpdate = true;
    }
  }
}
```

### Shockwave Rings
```javascript
// In shared/vfx/shockwave.js
class ShockwaveManager {
  constructor() {
    this.shockwaves = [];
    // Pre-create geometry/material for pooling
    this.geometry = new THREE.RingGeometry(0.1, 0.2, 32);
    this.baseMaterial = new THREE.MeshBasicMaterial({
      color: 0xffffff,
      transparent: true,
      opacity: 1,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending
    });
  }

  spawn(position, radiusMax = 3, duration = 0.3) {
    const material = this.baseMaterial.clone(); // Clone for independent opacity
    const mesh = new THREE.Mesh(this.geometry, material);

    mesh.position.copy(position);
    mesh.rotation.x = -Math.PI / 2; // Lie flat on XZ plane

    this.shockwaves.push({
      mesh: mesh,
      radiusMax: radiusMax,
      duration: duration,
      startTime: performance.now() / 1000
    });

    scene.add(mesh);
  }

  update(dt) {
    const now = performance.now() / 1000;

    for (let i = this.shockwaves.length - 1; i >= 0; i--) {
      const sw = this.shockwaves[i];
      const age = now - sw.startTime;
      const t = age / sw.duration;

      if (t >= 1) {
        // Remove and dispose
        scene.remove(sw.mesh);
        sw.material.dispose();
        this.shockwaves.splice(i, 1);
        continue;
      }

      // Scale up + fade out
      const scale = t * sw.radiusMax / 0.2; // Normalize to initial geometry size
      sw.mesh.scale.set(scale, scale, 1);
      sw.mesh.material.opacity = (1 - t) * 0.8;
    }
  }
}
