### Floating Score Text (3D Billboard + HTML Hybrid)
```javascript
// In shared/vfx/floatingText.js
class FloatingTextManager {
  constructor() {
    this.texts = [];
    this.canvasPool = []; // Reuse canvases for textures

    // HTML container for DOM-based floating text option
    this.htmlContainer = document.createElement('div');
    this.htmlContainer.className = 'floating-text-container';
    document.body.appendChild(this.htmlContainer);
  }

  spawn3D(position, text, color = '#00ff00', size = 24) {
    const canvas = this.getCanvas();
    const ctx = canvas.getContext('2d');

    ctx.fillStyle = 'rgba(0,0,0,0)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.font = `bold ${size}px Arial`;
    ctx.fillStyle = color;
    ctx.textAlign = 'center';
    ctx.fillText(text, canvas.width / 2, canvas.height / 2 + size / 3);

    const texture = new THREE.CanvasTexture(canvas);
    const material = new THREE.SpriteMaterial({ 
      map: texture,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending
    });

    const sprite = new THREE.Sprite(material);
    sprite.position.copy(position);
    sprite.scale.set(2, 1, 1); // Adjust for aspect ratio

    this.texts.push({
      mesh: sprite,
      lifetime: 1.5,
      velocityY: 0.5,
      htmlElement: null
    });

    scene.add(sprite);
  }

  spawnHTML(screenX, screenY, text, color = '#00ff00') {
    const el = document.createElement('div');
    el.className = 'floating-text';
    el.textContent = text;
    el.style.color = color;
    el.style.left = `${screenX}px`;
    el.style.top = `${screenY}px`;
    el.style.textShadow = `0 0 10px ${color}`;

    this.htmlContainer.appendChild(el);

    // Animate with CSS
    requestAnimationFrame(() => {
      el.animate([
        { opacity: 1, transform: 'translateY(0)' },
        { opacity: 0, transform: 'translateY(-30px)' }
      ], {
        duration: 1000,
        easing: 'ease-out'
      });
    });

    // Auto-remove after animation
    setTimeout(() => el.remove(), 1000);
  }

  update(dt) {
    for (let i = this.texts.length - 1; i >= 0; i--) {
      const ft = this.texts[i];

      ft.mesh.position.y += ft.velocityY * dt;
      ft.lifetime -= dt;
      ft.mesh.material.opacity = Math.max(0, ft.lifetime / 1.5);

      if (ft.lifetime <= 0) {
        scene.remove(ft.mesh);
        ft.material.dispose();
        this.texts.splice(i, 1);
      }
    }
  }

  getCanvas() {
    if (this.canvasPool.length > 0) {
      return this.canvasPool.pop();
    }
    const canvas = document.createElement('canvas');
    canvas.width = 128;
    canvas.height = 64;
    return canvas;
  }
}
